#include <iostream>

class Widget {
    inline static int count_ = 0;   // C++17 内联静态成员，所有对象共享
public:
    Widget() { ++count_; }
    static int live() { return count_; }
};

int main() {
    Widget a;
    {
        Widget b;                   // 离开作用域析构，但计数器不减（无析构逻辑）
    }
    std::cout << Widget::live();
}
